require_once dirname(__DIR__,2).'/src/media.php';require_method('POST');$u=current_user();$d=request_json();$id=(string)($d['id']??'');$media=(string)($d['media_id']??'');$label=(string)($d['label']??'');$audience=$d['audience']??'public';
$extra=$d['extra']??null;if($extra!==null&&(!is_array($extra)||strlen(json_encode($extra))>2000))json_response(['error'=>['code'=>'invalid_extra','message'=>'Invalid story details']],400);
if(!valid_uuid($id)||strlen($label)>80||!in_array($audience,['public','close_friends'],true))json_response(['error'=>['code'=>'invalid_story','message'=>'Invalid story fields']],400);
mutate($u,$d,'story.create',function($pdo)use($u,$id,$media,$label,$audience,$extra){if(isset($extra['audio_media_id']))owned_media((string)$extra['audio_media_id'],$u['id'],'audio/');$m=owned_media($media,$u['id']);if(!str_starts_with($m['mime_type'],'image/')&&!str_starts_with($m['mime_type'],'video/'))throw new DomainException('Stories require image or video');$q=$pdo->prepare('INSERT INTO stories(id,owner_id,media_id,label,audience,extra,created_at,expires_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 24 HOUR))');$q->execute([$id,$u['id'],$media,$label,$audience,$extra===null?null:json_encode($extra,JSON_UNESCAPED_UNICODE)]);$q=$pdo->prepare('SELECT * FROM stories WHERE id=?');$q->execute([$id]);return ['story'=>$q->fetch()];});
